verus! {
    // Given two vectors `a` and `b` of equal length,
    // produce a vector of booleans `result` of the same length
    // where result[i] == (a[i] >= b[i]).
    fn greater_equal(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
        requires
            a.len() == b.len(),
        ensures
            result.len() == a.len(),
        ensures
            forall|i: usize| i < a.len() ==> result[i] == (a[i] >= b[i])
    {
        let n = a.len();
        let mut result: Vec<bool> = Vec::new();
        let mut i: usize = 0;
        // We build `result` one element at a time.
        while i < n
            invariant
                i <= n,
                result.len() == i,
                // All previously pushed entries satisfy the specification
                forall|j: usize| j < i ==> result[j] == (a[j] >= b[j]),
            decreases
                n - i
        {
            let cmp = a[i] >= b[i];
            result.push(cmp);
            i = i + 1;
        }
        result
    }
}

